```javascript
// JSON method (loses functions, Dates, symbols)
const copy = JSON.parse(JSON.stringify(original));

// Or with lodash
const copy = _.cloneDeep(original);

// Manual recursion
function deepCopy(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  if (obj instanceof Date) return new Date(obj);
  if (obj instanceof Array) return obj.map(deepCopy);
  const result = {};
  for (const key in obj) {
    if (obj.hasOwnProperty(key)) result[key] = deepCopy(obj[key]);
  }
  return result;
}
```

Python equivalent:
```python
import copy
original = {'db': {'host': 'localhost', 'port': 5432}, 'debug': True}
settings = copy.deepcopy(original)
settings['db']['host'] = 'remote.com'
print(original['db']['host'])  # 'localhost' — unchanged
```

`structuredClone()` handles most types (objects, arrays, Maps, Sets, Dates, etc.). JSON method is lighter but strips functions; use it only for JSON-serializable data.
